# Geospatial search: haversine distance ranks points by true earth-surface distance.
import math
points = {'NYC': (40.71, -74.0), 'Boston': (42.36, -71.06), 'LA': (34.05, -118.24)}
def haversine(lat1, lon1, lat2, lon2):
    R = 6371.0
    p1, p2 = math.radians(lat1), math.radians(lat2)
    dp = math.radians(lat2 - lat1); dl = math.radians(lon2 - lon1)
    a = math.sin(dp/2)**2 + math.cos(p1)*math.cos(p2)*math.sin(dl/2)**2
    return 2 * R * math.asin(math.sqrt(a))
qlat, qlon, radius = 40.7, -74.0, 500
print(f"Within {radius} km of ({qlat}, {qlon}):")
for name, (la, lo) in points.items():
    d = haversine(qlat, qlon, la, lo)
    if d <= radius:
        print(f"  {name}: {d:.1f} km")

